/**
 * Format kebab-case slug into human readable title
 * e.g. "uptime-kuma" -> "Uptime Kuma", "paperless-ngx" -> "Paperless NGX"
 */
export function formatIconTitle(slug) {
  if (!slug) return "";
  return slug
    .split("-")
    .map(w => {
      if (w.toLowerCase() === "ngx") return "NGX";
      if (w.toLowerCase() === "pdf") return "PDF";
      if (w.toLowerCase() === "vpn") return "VPN";
      if (w.toLowerCase() === "ai") return "AI";
      if (w.toLowerCase() === "ui") return "UI";
      if (w.toLowerCase() === "dns") return "DNS";
      if (w.toLowerCase() === "os") return "OS";
      if (w.toLowerCase() === "tv") return "TV";
      if (w.toLowerCase() === "iot") return "IoT";
      return w.charAt(0).toUpperCase() + w.slice(1);
    })
    .join(" ");
}
